def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        match = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = "".join(ch for ch in value if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        return digits

    def valid_phone(value):
        return len(value) == 10 and value[0] not in "01"

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            value = value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    def normalized_row(row, index):
        email = normalize_email(row["email"])
        email = email if valid_email(email) else ""
        phone = normalize_phone(row["phone"])
        phone = phone if valid_phone(phone) else ""
        last_name = normalize_name(row["last_name"])
        updated = parse_updated(row["updated"])
        source = row["source"].strip().lower()

        return {
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": last_name,
            "zip": normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": source,
            "updated_dt": updated,
            "opted_out": opted_out(row["opted_out"]),
            "tags": row["tags"],
        }

    normalized = []
    for index, row in enumerate(rows):
        item = normalized_row(row, index)
        if item["email"] or item["phone"]:
            normalized.append(item)

    # Build connected components for the transitive matching rule.
    parent = list(range(len(normalized)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    by_email = {}
    by_phone_name = {}
    for i, row in enumerate(normalized):
        if row["email"]:
            if row["email"] in by_email:
                union(i, by_email[row["email"]])
            else:
                by_email[row["email"]] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in by_phone_name:
                union(i, by_phone_name[key])
            else:
                by_phone_name[key] = i

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    def choose(group, field, require_valid=False):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""
        candidates.sort(
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["index"],
            ),
            reverse=True,
        )
        return candidates[0][field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(row["index"] for row in g)):
        latest = max(row["updated_dt"] for row in group)

        def tags_for_group():
            values = set()
            for row in group:
                for tag in re.split(r"[;,]", row["tags"]):
                    tag = tag.strip().lower()
                    if tag:
                        values.add(tag)
            return ";".join(sorted(values))

        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": tags_for_group(),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
